<?php
require_once __DIR__ . '/../config.php';
if (session_status() !== PHP_SESSION_ACTIVE) { session_set_cookie_params(['httponly'=>true,'samesite'=>'Lax','secure'=>!empty($_SERVER['HTTPS'])]); session_start(); }
header('Content-Type: application/json; charset=utf-8'); header('X-Content-Type-Options: nosniff');
function respond($data, int $status=200): void { http_response_code($status); echo json_encode($data, JSON_UNESCAPED_UNICODE); exit; }
function body(): array { $d=json_decode(file_get_contents('php://input') ?: '{}',true); return is_array($d)?$d:[]; }
function text_value(array $d,string $key,int $max,bool $required=true): string { $v=trim((string)($d[$key]??'')); if(($required && $v==='') || mb_strlen($v)>$max) respond(['success'=>false,'message'=>"Please enter a valid {$key} (maximum {$max} characters)."],422); return $v; }
function user(): ?array { return isset($_SESSION['user']) && is_array($_SESSION['user']) ? $_SESSION['user'] : null; }
function need_login(): array { $u=user(); if(!$u) respond(['success'=>false,'message'=>'Please log in first.'],401); return $u; }
function need_admin(): array { $u=need_login(); if($u['role']!=='admin') respond(['success'=>false,'message'=>'Administrator access is required.'],403); return $u; }
function need_student(): array { $u=need_login(); if($u['role']!=='student') respond(['success'=>false,'message'=>'Student access is required.'],403); return $u; }
function method(string $expected): void { if($_SERVER['REQUEST_METHOD']!==$expected) respond(['success'=>false,'message'=>$expected.' required.'],405); }
try { $pdo=db(); $action=(string)($_GET['action']??''); $d=body();
 switch($action) {
  case 'me': $u=user(); respond(['success'=>true,'data'=>$u]);
  case 'register':
   method('POST'); $name=text_value($d,'name',100); $email=strtolower(text_value($d,'email',190)); $phone=text_value($d,'phone',30,false); $password=(string)($d['password']??''); if(!filter_var($email,FILTER_VALIDATE_EMAIL)) respond(['success'=>false,'message'=>'Enter a valid email address.'],422); if(strlen($password)<8) respond(['success'=>false,'message'=>'Password must be at least 8 characters.'],422);
   $pdo->beginTransaction(); try { $check=$pdo->prepare('SELECT id FROM users WHERE email=?');$check->execute([$email]);if($check->fetch()){$pdo->rollBack();respond(['success'=>false,'message'=>'This email already has an account. Please log in instead.'],409);} $check=$pdo->prepare('SELECT id FROM students WHERE email=?');$check->execute([$email]);$existing=$check->fetch();if($existing){$sid=(int)$existing['id'];$st=$pdo->prepare('UPDATE students SET name=?,phone=? WHERE id=?');$st->execute([$name,$phone?:null,$sid]);}else{$st=$pdo->prepare('INSERT INTO students(name,email,phone) VALUES(?,?,?)');$st->execute([$name,$email,$phone?:null]);$sid=(int)$pdo->lastInsertId();} $st=$pdo->prepare("INSERT INTO users(student_id,name,email,password_hash,role) VALUES(?,?,?,?, 'student')"); $st->execute([$sid,$name,$email,password_hash($password,PASSWORD_DEFAULT)]); $uid=(int)$pdo->lastInsertId(); $pdo->commit(); } catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack(); if($e instanceof PDOException && $e->getCode()==='23000') respond(['success'=>false,'message'=>'This email is already registered. Please log in instead.'],409); throw $e; }
   session_regenerate_id(true); $_SESSION['user']=['id'=>$uid,'student_id'=>$sid,'name'=>$name,'email'=>$email,'role'=>'student']; respond(['success'=>true,'message'=>'Student account created.','data'=>$_SESSION['user']]);
  case 'login':
   method('POST'); $email=strtolower(text_value($d,'email',190)); $password=(string)($d['password']??''); $st=$pdo->prepare('SELECT id,student_id,name,email,password_hash,role FROM users WHERE email=? LIMIT 1'); $st->execute([$email]); $row=$st->fetch(); if(!$row || !password_verify($password,$row['password_hash'])) respond(['success'=>false,'message'=>'Email or password is incorrect.'],401); session_regenerate_id(true); $_SESSION['user']=['id'=>(int)$row['id'],'student_id'=>$row['student_id']?(int)$row['student_id']:null,'name'=>$row['name'],'email'=>$row['email'],'role'=>$row['role']]; respond(['success'=>true,'message'=>'Login successful.','data'=>$_SESSION['user']]);
  case 'logout': method('POST'); $_SESSION=[]; if(ini_get('session.use_cookies')){$params=session_get_cookie_params();setcookie(session_name(),'',time()-42000,$params['path'],$params['domain'],$params['secure'],$params['httponly']);} session_destroy(); respond(['success'=>true,'message'=>'Logged out.']);
  case 'dashboard':
   $u=need_login(); if($u['role']==='admin') { $data=['total_students'=>(int)$pdo->query("SELECT COUNT(*) FROM students")->fetchColumn(),'available_rooms'=>(int)$pdo->query('SELECT COUNT(*) FROM rooms WHERE occupied<capacity')->fetchColumn(),'pending_requests'=>(int)$pdo->query("SELECT COUNT(*) FROM room_requests WHERE status='Pending'")->fetchColumn(),'open_complaints'=>(int)$pdo->query("SELECT COUNT(*) FROM complaints WHERE status NOT IN ('Resolved','Closed')")->fetchColumn()]; }
   else { $sid=(int)$u['student_id']; $st=$pdo->prepare("SELECT r.room_number,r.room_type FROM room_allocations a JOIN rooms r ON r.id=a.room_id WHERE a.student_id=? AND a.status='Active' LIMIT 1");$st->execute([$sid]);$room=$st->fetch();$st=$pdo->prepare('SELECT COUNT(*) FROM room_requests WHERE student_id=?');$st->execute([$sid]);$req=(int)$st->fetchColumn();$st=$pdo->prepare("SELECT COUNT(*) FROM fees WHERE student_id=? AND status<>'Paid'");$st->execute([$sid]);$fees=(int)$st->fetchColumn();$st=$pdo->prepare("SELECT COUNT(*) FROM complaints WHERE student_id=?");$st->execute([$sid]);$comps=(int)$st->fetchColumn();$data=['my_room'=>$room?:null,'my_requests'=>$req,'my_pending_fees'=>$fees,'my_complaints'=>$comps]; } respond(['success'=>true,'data'=>$data]);
  case 'rooms': need_login(); respond(['success'=>true,'data'=>$pdo->query('SELECT id,room_number,room_type,capacity,occupied,monthly_fee FROM rooms ORDER BY room_number')->fetchAll()]);
  case 'students': need_admin(); $rows=$pdo->query("SELECT s.id,s.name,s.email,s.phone,s.status,r.room_number FROM students s LEFT JOIN room_allocations a ON a.student_id=s.id AND a.status='Active' LEFT JOIN rooms r ON r.id=a.room_id ORDER BY s.id DESC")->fetchAll(); respond(['success'=>true,'data'=>$rows]);
  case 'requests': $u=need_login(); if($u['role']==='admin'){$rows=$pdo->query('SELECT q.id,s.name AS student_name,s.email,r.room_number,q.room_id,q.request_date,q.status FROM room_requests q JOIN students s ON s.id=q.student_id JOIN rooms r ON r.id=q.room_id ORDER BY q.id DESC LIMIT 100')->fetchAll();}else{$st=$pdo->prepare('SELECT q.id,s.name AS student_name,r.room_number,q.room_id,q.request_date,q.status FROM room_requests q JOIN students s ON s.id=q.student_id JOIN rooms r ON r.id=q.room_id WHERE q.student_id=? ORDER BY q.id DESC');$st->execute([(int)$u['student_id']]);$rows=$st->fetchAll();} respond(['success'=>true,'data'=>$rows]);
  case 'fees': $u=need_login(); if($u['role']==='admin'){$rows=$pdo->query('SELECT f.id,s.name AS student_name,f.month_label,f.amount,f.due_date,f.status FROM fees f JOIN students s ON s.id=f.student_id ORDER BY f.id DESC LIMIT 200')->fetchAll();}else{$st=$pdo->prepare('SELECT f.id,s.name AS student_name,f.month_label,f.amount,f.due_date,f.status FROM fees f JOIN students s ON s.id=f.student_id WHERE f.student_id=? ORDER BY f.id DESC');$st->execute([(int)$u['student_id']]);$rows=$st->fetchAll();} respond(['success'=>true,'data'=>$rows]);
  case 'complaints': $u=need_login(); if($u['role']==='admin'){$rows=$pdo->query('SELECT id,student_name,category,details,status,DATE_FORMAT(created_at,"%d %b %Y") AS created_at FROM complaints ORDER BY id DESC LIMIT 100')->fetchAll();}else{$st=$pdo->prepare('SELECT id,student_name,category,details,status,DATE_FORMAT(created_at,"%d %b %Y") AS created_at FROM complaints WHERE student_id=? ORDER BY id DESC');$st->execute([(int)$u['student_id']]);$rows=$st->fetchAll();} respond(['success'=>true,'data'=>$rows]);
  case 'add_student':
   need_admin(); method('POST'); $name=text_value($d,'name',100);$email=strtolower(text_value($d,'email',190));$phone=text_value($d,'phone',30,false);if(!filter_var($email,FILTER_VALIDATE_EMAIL))respond(['success'=>false,'message'=>'Enter a valid email address.'],422);$st=$pdo->prepare('INSERT INTO students(name,email,phone) VALUES(?,?,?)');try{$st->execute([$name,$email,$phone?:null]);}catch(PDOException $e){if($e->getCode()==='23000')respond(['success'=>false,'message'=>'A student with this email already exists.'],409);throw $e;}respond(['success'=>true,'message'=>'Student added.']);
  case 'request_room':
   $u=need_student(); method('POST');$room=(int)($d['room_id']??0);$st=$pdo->prepare('SELECT capacity,occupied FROM rooms WHERE id=?');$st->execute([$room]);$r=$st->fetch();if(!$r)respond(['success'=>false,'message'=>'Room not found.'],404);if((int)$r['occupied']>=(int)$r['capacity'])respond(['success'=>false,'message'=>'This room is full. Please choose an available room.'],409);$st=$pdo->prepare("SELECT COUNT(*) FROM room_allocations WHERE student_id=? AND status='Active'");$st->execute([(int)$u['student_id']]);if((int)$st->fetchColumn()>0)respond(['success'=>false,'message'=>'You already have an allocated room.'],409);$st=$pdo->prepare("SELECT COUNT(*) FROM room_requests WHERE student_id=? AND status='Pending'");$st->execute([(int)$u['student_id']]);if((int)$st->fetchColumn()>0)respond(['success'=>false,'message'=>'You already have a pending room request.'],409);$st=$pdo->prepare("INSERT INTO room_requests(student_id,room_id,status) VALUES(?,?,'Pending')");$st->execute([(int)$u['student_id'],$room]);respond(['success'=>true,'message'=>'Room request submitted. You can track it under My room requests.']);
  case 'add_complaint':
   $u=need_login(); method('POST');$category=text_value($d,'category',50);$details=text_value($d,'details',1000);$allowed=['Maintenance','Cleanliness','Noise','Internet','Other'];if(!in_array($category,$allowed,true))respond(['success'=>false,'message'=>'Choose a valid complaint category.'],422);if($u['role']==='student'){$sid=(int)$u['student_id'];$name=$u['name'];}else{$name=text_value($d,'student_name',100);$sid=null;} $st=$pdo->prepare('INSERT INTO complaints(student_id,student_name,category,details) VALUES(?,?,?,?)');$st->execute([$sid,$name,$category,$details]);respond(['success'=>true,'message'=>'Complaint submitted.']);
  case 'request_status':
   need_admin();method('POST');$id=(int)($d['id']??0);$status=(string)($d['status']??'');if($id<1||!in_array($status,['Approved','Rejected'],true))respond(['success'=>false,'message'=>'Invalid request or status.'],422);$pdo->beginTransaction();$st=$pdo->prepare('SELECT student_id,room_id,status FROM room_requests WHERE id=? FOR UPDATE');$st->execute([$id]);$req=$st->fetch();if(!$req){$pdo->rollBack();respond(['success'=>false,'message'=>'Request not found.'],404);}if($req['status']!=='Pending'){$pdo->rollBack();respond(['success'=>false,'message'=>'This request has already been reviewed.'],409);}if($status==='Approved'){$st=$pdo->prepare('SELECT capacity,occupied FROM rooms WHERE id=? FOR UPDATE');$st->execute([$req['room_id']]);$r=$st->fetch();if(!$r||(int)$r['occupied']>=(int)$r['capacity']){$pdo->rollBack();respond(['success'=>false,'message'=>'This room is full.'],409);}$st=$pdo->prepare("SELECT COUNT(*) FROM room_allocations WHERE student_id=? AND status='Active'");$st->execute([$req['student_id']]);if((int)$st->fetchColumn()>0){$pdo->rollBack();respond(['success'=>false,'message'=>'This student already has an active room allocation.'],409);}$pdo->prepare("INSERT INTO room_allocations(student_id,room_id,status) VALUES(?,?,'Active')")->execute([$req['student_id'],$req['room_id']]);$pdo->prepare('UPDATE rooms SET occupied=occupied+1 WHERE id=?')->execute([$req['room_id']]);$pdo->prepare("UPDATE room_requests SET status='Rejected' WHERE student_id=? AND id<>? AND status='Pending'")->execute([$req['student_id'],$id]);}$pdo->prepare('UPDATE room_requests SET status=? WHERE id=?')->execute([$status,$id]);$pdo->commit();respond(['success'=>true,'message'=>'Request updated.']);
  case 'add_fee': need_admin(); method('POST'); $sid=(int)($d['student_id']??0); $month=text_value($d,'month_label',30); $amount=(float)($d['amount']??0); $due=text_value($d,'due_date',10); if($sid<1||$amount<=0||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$due))respond(['success'=>false,'message'=>'Enter a student, valid amount and due date.'],422); $st=$pdo->prepare('SELECT id FROM students WHERE id=?');$st->execute([$sid]);if(!$st->fetch())respond(['success'=>false,'message'=>'Student not found.'],404);$st=$pdo->prepare("INSERT INTO fees(student_id,month_label,amount,due_date,status) VALUES(?,?,?,?,'Pending')");$st->execute([$sid,$month,$amount,$due]);respond(['success'=>true,'message'=>'Fee record added.']);
  case 'fee_paid': need_admin();method('POST');$id=(int)($d['id']??0);if($id<1)respond(['success'=>false,'message'=>'Invalid fee ID.'],422);$st=$pdo->prepare("UPDATE fees SET status='Paid' WHERE id=? AND status<>'Paid'");$st->execute([$id]);if(!$st->rowCount())respond(['success'=>false,'message'=>'Fee was not found or is already paid.'],409);respond(['success'=>true,'message'=>'Fee updated.']);
  case 'complaint_resolve': need_admin();method('POST');$id=(int)($d['id']??0);if($id<1)respond(['success'=>false,'message'=>'Invalid complaint ID.'],422);$st=$pdo->prepare("UPDATE complaints SET status='Resolved' WHERE id=? AND status NOT IN ('Resolved','Closed')");$st->execute([$id]);if(!$st->rowCount())respond(['success'=>false,'message'=>'Complaint was not found or is already resolved.'],409);respond(['success'=>true,'message'=>'Complaint resolved.']);
  default: respond(['success'=>false,'message'=>'Unknown API action.'],404);
 }
} catch(PDOException $e) { error_log($e->getMessage()); respond(['success'=>false,'message'=>'Database error. Check config.php and import database.sql in phpMyAdmin.'],500); } catch(Throwable $e) { error_log($e->getMessage()); respond(['success'=>false,'message'=>'Unexpected server error. Check the PHP error log.'],500); }
